  'plans.autoRenewDisclosure': 'ખરીદીની પુષ્ટિ પર તમારું ચુકવણી તમારા Apple ખાતામાં ચાર્જ કરવામાં આવશે. સબ્સ્ક્રિપ્શન આપોઆપ સમાન કિંમત અને સમયગાળા માટે નવીનીકરણ થાય છે, જો કે વર્તમાન સમયગાળાના અંત પહેલા ઓછામાં ઓછા 24 કલાક રદ કરવામાં આવે. સેટિંગ્સ → [તમારું નામ] → સબ્સ્ક્રિપ્શનમાં કોઈપણ સમયે વ્યવસ્થાપિત અથવા રદ કરો.',
