  'plans.storageWarning': 'તમે {used} માંથી {total} નો ઉપયોગ કરી રહ્યા છો',
  'plans.storageWarningUpgrade': 'Chatyy One માટે અપગ્રેડ કરો અને 200 GB મેળવો!',
  'plans.faqWhatIsPlus': 'Chatyy One શું છે?',
  'plans.faqWhatIsPlusAnswer': 'આ Chatyy ની પ્રીમિયમ યોજના છે જે તમારી તમામ વાતચીત, ફોટા અને વિડિઓઝને સુરક્ષિત કરે છે. Chatyy One સાથે, જો તમે અજાણમાં કંઈક મિટાવો છો, તો તમે 30 દિવસમાં પુનઃપ્રાપ્ત કરી શકો છો. ઉપરાંત, તમને 200GB સ્ટોરેજ, One AI તરીકે વ્યક્તિગત સહાયક, અને 100MB સુધીની ફાઇલો મોકલવાની ક્ષમતા મળે છે.',
  'plans.faqCancelAnswer': 'તમારી યોજના ચૂકવેલ સમયગાળા સુધી સક્રિય રહે છે. ત્યારબાદ, તમે મફત યોજનામાં પાછા જશો. 15GB કરતા વધુના તમારા ફોટા અને વિડિઓઝ 30 દિવસ સુધી ડાઉનલોડ કરવા માટે રાખવામાં આવશે.',
  'plans.faqHowFamily': 'પ્રો યોજના કેવી રીતે કાર્ય કરે છે?',
  'plans.faqHowFamilyAnswer': 'તમે તમારા પરિવારના 4 લોકો સુધી ઉમેરવા માટે સક્ષમ છો. બધા 500GB સ્ટોરેજને શેર કરે છે અને Chatyy One ના તમામ લાભો મેળવે છે. દરેક વ્યક્તિને પોતાનો ખાનગી જગ્યા મળે છે - કોઈપણને બીજાના ફાઇલો દેખાતા નથી.',
  'plans.faqChangePlanAnswer': 'હા! જો તમે Plus થી Pro માટે અપગ્રેડ કરો છો, તો ફક્ત પ્રમાણભૂત તફાવત જ ચાર્જ કરવામાં આવશે. જો તમે ડાઉનગ્રેડ કરો છો, તો વર્તમાન યોજના સમયગાળા સુધી જ રહેશે.',
  'plans.faqCardDeclined': 'મારું કાર્ડ નકારી દેવામાં આવ્યું, હું શું કરું?',
  'plans.faqCardDeclinedAnswer': 'તમારે તમારા કાર્ડને અપડેટ કરવા માટે 7 દિવસ છે. આ સમયગાળા દરમિયાન, તમારા તમામ લાભો કાર્યરત રહે છે. 7 દિવસ પછી, યોજના મફત પર પાછા જાશે.',
  'plans.faqDataSafe': 'મારા ડેટા સુરક્ષિત છે?',
  'plans.faqDataSafeAnswer': 'હા! તમારા ચુકવણીના ડેટા અંત-થી-અંતે એન્ક્રિપ્શન સાથે પ્રક્રિયા કરવામાં આવે છે. અમે તમારા કાર્ડનો નંબર સંગ્રહિત નથી કરતા - ફક્ત તમારા સંદર્ભ માટે છેલ્લા 4 અંક.',
