  'contactsConsent.body': 'તમારા કયા મિત્રો પહેલેથી જ Chatyy માં છે તે બતાવવા માટે, અમે તમારા સંપર્કોના ફોન નંબર અને ઈમેઇલ્સને અમારા સર્વર પર એન્ક્રિપ્ટેડ રીતે (હેશ SHA-256) મોકલશું. સંપર્કો તપાસ પછી સંગ્રહિત નથી અને ક્યારેય કોઈ સાથે શેર કરવામાં આવતી નથી. તમે ક્યારે પણ સેટિંગ્સ → ગોપનીયતા માંથી પરવાનગી પાછી ખેંચી શકો છો.',
